import yaml,re
src=open('claude-dev-log-diary/day-003.md').read()
flat=re.sub(r'\s+',' ',src)
d=yaml.safe_load(open('.coordination/mining/v2/day-003.yaml'))
miss=[]
def chk(q,tag):
    if not q: return
    f=re.sub(r'\s+',' ',q).strip()
    if f not in flat: miss.append((tag,f[:90]))
for p in d['philosophy']: chk(p.get('quote'),'phil '+p['loc'])
for r in d['skill_rules']: chk(r.get('quote'),'rule '+r['rule_id'])
for f in d['failure_modes']: chk(f.get('quote'),'fm '+f['loc'])
for pr in d['pairing_rules']: chk(pr.get('quote'),'pair '+pr['rule_id'])
print('MISSING QUOTES:',len(miss))
for m in miss: print(m)
